```ts
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;
const TMP_TTL_MS = 24 * HOUR_MS;

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

export class ChatRoom extends DurableObject<Env> {
  // Each write waits for the previous one to settle, so async writes run in order.
  private writeChain: Promise<unknown> = Promise.resolve();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS kv (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL,
          updated_at INTEGER NOT NULL
        )
      `);
      // Start the hourly chain once. alarm() schedules the next run.
      if ((await ctx.storage.getAlarm()) === null) {
        await ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  private serialize<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.writeChain.then(fn);
    this.writeChain = run.catch(() => {});
    return run;
  }

  async get<T = unknown>(key: string): Promise<T | null> {
    const row = this.ctx.storage.sql
      .exec<{ value: string }>("SELECT value FROM kv WHERE key = ?", key)
      .toArray()[0];
    return row ? (JSON.parse(row.value) as T) : null;
  }

  set(key: string, value: unknown): Promise<void> {
    return this.serialize(async () => {
      this.ctx.storage.sql.exec(
        `INSERT INTO kv (key, value, updated_at) VALUES (?, ?, ?)
         ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
        key,
        JSON.stringify(value),
        Date.now(),
      );
    });
  }

  async alarm(): Promise<void> {
    // Schedule the next run first, so a failure below does not stop the hourly wake.
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);

    await this.serialize(async () => {
      // Run SQL directly here. Calling set() from inside serialize() would wait on itself.
      this.ctx.storage.sql.exec(
        "DELETE FROM kv WHERE key LIKE 'tmp:%' AND updated_at < ?",
        Date.now() - TMP_TTL_MS,
      );
      this.ctx.storage.sql.exec(
        `INSERT INTO kv (key, value, updated_at) VALUES ('last_tick', ?, ?)
         ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
        JSON.stringify(Date.now()),
        Date.now(),
      );
    });
  }
}
```

The matching config goes in `wrangler.jsonc`:

```jsonc
{
  "durable_objects": {
    "bindings": [{ "name": "CHAT_ROOM", "class_name": "ChatRoom" }]
  },
  "migrations": [{ "tag": "v1", "new_sqlite_classes": ["ChatRoom"] }]
}
```

Route to a room with `env.CHAT_ROOM.getByName(roomId)`. The `set()` queue matters only when a write awaits something external. The synchronous SQL in `alarm()` is already atomic under the object's input gate. Reads do not wait for queued writes, so `get()` can return the value from before a pending `set()`. Storage calls in the constructor and `alarm()` may need `await`s on your runtime, so run it once in `wrangler dev` to confirm the alarm fires.

I wrote the class in the chat only and did not touch any files in the repo.
